INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C1','kor',2,1,'u8',1,'작품 감상 경험과 시 낭송 — 그림책·시·인형극을 감상한 경험을 나누고, 「우산 사용법」을 낭송하며 따뜻하고 정다운 느낌을 말하기',ARRAY['2국05-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C2','kor',2,1,'u8',1,'장면을 보고 인물의 마음 상상하기 — 「흥부와 놀부」·「콩쥐팥쥐」·「팥죽 할멈과 호랑이」·「별주부전」 장면에서 인물이 처한 상황을 떠올려 마음 상상하기',ARRAY['2국05-03']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C3','kor',2,1,'u8',3,'「신호」 내용과 인물의 마음 — 건널목에서 마주친 두 친구가 몸짓 신호를 주고받는 장면을 상상하고, 감정 낱말 없이도 웃고 뛰는 행동에서 반가운 마음 짐작하기',ARRAY['2국05-03']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C4','kor',2,1,'u8',3,'흉내 내는 말 — 빙긋·까딱·휘휘·폴짝폴짝이 나타내는 모양을 알고 장면에 맞게 쓰기',ARRAY['2국05-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C5','kor',2,1,'u8',3,'여러 가지 방법으로 시 낭송하기 — 주고받으며·몸짓으로 표현하며 낭송하고, 신호를 주고받고 싶은 사람과 나만의 신호 만들기',ARRAY['2국01-05']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C6','kor',2,1,'u8',5,'「편지」 내용과 차례 — 편지를 기다리며 슬퍼하는 두꺼비, 편지를 써서 달팽이에게 부탁한 개구리, 나흘 뒤 편지를 받고 기뻐한 두꺼비의 차례 정리하기',ARRAY['2국05-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C7','kor',2,1,'u8',5,'말과 행동으로 인물의 마음 짐작하기 — 「너 슬퍼 보인다」·서둘러 편지 쓰기·「와, 정말로 멋진 편지다」에서 개구리와 두꺼비의 마음 짐작하기',ARRAY['2국05-03']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C8','kor',2,1,'u8',5,'이야기를 읽고 생각이나 느낌 쓰기 — 기억에 남는 장면, 그 까닭, 그 장면에 대한 나의 생각을 담아 짧게 쓰고 발표하기',ARRAY['2국05-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C9','kor',2,1,'u8',7,'「해와 달이 된 오누이」 인형극 — 그림자 인형극을 감상하고 엄마의 당부·똘이의 지혜·호랑이의 최후와 오누이·동아줄·나그네의 뜻 알기',ARRAY['2국06-01']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C10','kor',2,1,'u8',7,'인형극에서 인물의 마음 짐작하기 — 인물의 행동, 마음이 드러나는 말, 목소리의 크기와 빠르기를 살펴 호랑이·오누이의 마음 짐작하기',ARRAY['2국05-03']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C11','kor',2,1,'u8',9,'「의좋은 형제」 인형극과 편지 — 형제가 서로 볏단을 옮긴 까닭과 차례, 재미있는 장면을 찾고 형이나 아우에게 생각이나 느낌을 담은 편지 쓰기',ARRAY['2국05-02']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C12','kor',2,1,'u8',12,'막대 인형극 만들고 발표하기 — 막대 인형을 간단히 만들어 한 장면을 인물의 마음이 드러나게 발표하고, 바른 자세로 감상하며 소감 나누기',ARRAY['2국01-05']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u8-C13','kor',2,1,'u8',12,'느낀 점 발표 방법과 연음 — 인물의 말과 행동·기억에 남는 장면과 까닭·비슷한 경험·하고 싶은 말로 느낀 점 발표하기, 구름이[구르미]처럼 받침이 넘어가는 소리 읽기',ARRAY['2국05-02']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
