INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X02','kor',2,'u8',ARRAY['K2-1-u8-C8','K2-1-u8-C13']::text[],'생각이나 느낌 대신 줄거리만 길게 말한다','장면 하나 + 내 생각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X03','kor',2,'u8',ARRAY['K2-1-u8-C3','K2-1-u8-C6','K2-1-u8-C9','K2-1-u8-C11']::text[],'작품에 없는 내용으로 답한다','작품에서 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X04','kor',2,'u8',ARRAY['K2-1-u8-C3','K2-1-u8-C7']::text[],'「기쁘다」 같은 감정 낱말이 없으면 마음을 알 수 없다고 여긴다','행동에도 마음이 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X05','kor',2,'u8',ARRAY['K2-1-u8-C4']::text[],'흉내 내는 말의 뜻을 헷갈린다','몸으로 흉내 내 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X06','kor',2,'u8',ARRAY['K2-1-u8-C5']::text[],'시 낭송은 틀리지 않고 크고 빠르게 읽는 것이라 여긴다','느낌을 담아 즐겁게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X07','kor',2,'u8',ARRAY['K2-1-u8-C6','K2-1-u8-C11']::text[],'일이 일어난 차례를 뒤섞는다','처음 → 가운데 → 끝') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X08','kor',2,'u8',ARRAY['K2-1-u8-C10']::text[],'인형극 인물의 마음을 인형 생김새로만 짐작한다','말·행동·목소리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X09','kor',2,'u8',ARRAY['K2-1-u8-C9']::text[],'오누이·동아줄·나그네의 뜻을 헷갈린다','이야기 속에서 뜻 짐작') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X10','kor',2,'u8',ARRAY['K2-1-u8-C8','K2-1-u8-C12']::text[],'친구의 감상이 나와 다르면 틀렸다고 여긴다','까닭을 들어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X11','kor',2,'u8',ARRAY['K2-1-u8-C12']::text[],'인형 꾸미기에 시간을 다 써서 인형극을 못 한다','간단히, 극에 집중') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X12','kor',2,'u8',ARRAY['K2-1-u8-C12']::text[],'인형극을 볼 때 떠들거나 끼어든다','바른 자세로 끝까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X13','kor',2,'u8',ARRAY['K2-1-u8-C13']::text[],'받침이 뒤로 넘어가는 소리를 무시하고 글자대로 끊어 읽는다','구름이 → [구르미]') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X14','kor',2,'u8',ARRAY['K2-1-u8-C7','K2-1-u8-C11']::text[],'인물이 그렇게 행동한 까닭을 잘못 안다','인물의 말에서 까닭 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u8-X15','kor',2,'u8',ARRAY['K2-1-u8-C2','K2-1-u8-C10']::text[],'인물이 처한 상황을 생각하지 않고 마음을 상상한다','무슨 일이 있었지?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
