INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_challenge#7','kor',2,1,'u8','L05','g2_1_kor_u8_L05_challenge','lesson_challenge','K2-1-u8-C8',3,'mc','auto','「편지」와 비슷한 경험으로 알맞은 것은?',ARRAY['K2-1-u8-X03']::text[],false,'{"seq":7,"concept":"K2-1-u8-C8","difficulty":3,"kind":"mc","stem":"「편지」와 비슷한 경험으로 알맞은 것은?","options":[{"t":"「할머니께 생일 축하 카드를 받아 정말 기뻤어.」","correct":true},{"t":"「어제 수학 문제를 풀었어.」","mis":"K2-1-u8-X03"},{"t":"「운동장이 넓어.」","mis":"K2-1-u8-X03"}],"explanation":["비슷한 경험이에요.","261쪽 예시예요.","자신과 관련짓기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_challenge#8','kor',2,1,'u8','L05','g2_1_kor_u8_L05_challenge','lesson_challenge','K2-1-u8-C6',4,'sa','auto','두꺼비가 편지를 받기까지 걸린 날을 「○○ 뒤」 꼴로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-1-u8-C6","difficulty":4,"kind":"sa","stem":"두꺼비가 편지를 받기까지 걸린 날을 「○○ 뒤」 꼴로 쓰세요.","answer":["나흘 뒤","나흘뒤","나흘"],"explanation":["나흘 뒤예요.","259쪽이에요.","이야기예요."],"asset":{"type":"scene","icon":"✉️","text":"「편지」(아놀드 로벨) — 편지를 못 받아 슬픈 두꺼비에게 개구리가 편지를 써서 달팽이에게 부탁해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_challenge#9','kor',2,1,'u8','L05','g2_1_kor_u8_L05_challenge','lesson_challenge','K2-1-u8-C8',4,'essay','teacher','263쪽 — 「편지」에서 기억에 남는 장면, 그 까닭, 그 장면에 대한 나의 생각을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u8-C8","difficulty":4,"kind":"essay","stem":"263쪽 — 「편지」에서 기억에 남는 장면, 그 까닭, 그 장면에 대한 나의 생각을 쓰세요.","answer_guide":{"answer":"예: 두꺼비가 편지를 받고 기뻐하는 장면이 기억에 남는다. 친구의 마음이 담긴 편지라서다. 나도 친구에게 편지를 써 주고 싶다.","scoring_points":["기억에 남는 장면과 까닭을 썼어요","그 장면에 대한 내 생각을 썼어요"]},"explanation":["생각이나 느낌 쓰기예요.","263쪽이에요.","보기예요."],"asset":{"type":"scene","icon":"✉️","text":"「편지」(아놀드 로벨) — 편지를 못 받아 슬픈 두꺼비에게 개구리가 편지를 써서 달팽이에게 부탁해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L05_challenge#10','kor',2,1,'u8','L05','g2_1_kor_u8_L05_challenge','lesson_challenge','K2-1-u8-C7',4,'essay','teacher','「편지」의 인물(개구리·두꺼비·달팽이) 가운데 한 명에게 하고 싶은 말을 편지로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u8-C7","difficulty":4,"kind":"essay","stem":"「편지」의 인물(개구리·두꺼비·달팽이) 가운데 한 명에게 하고 싶은 말을 편지로 쓰세요.","answer_guide":{"answer":"예: 달팽이에게 — 나흘이나 걸려 편지를 전해 주다니 정말 대단해. 두 친구가 기뻐해서 너도 보람을 느꼈을 것 같아.","scoring_points":["인물을 골랐어요","인물의 마음을 생각한 말을 썼어요"]},"explanation":["인물에게 편지예요.","지도서 329쪽이에요.","예시예요."],"asset":{"type":"scene","icon":"✉️","text":"「편지」(아놀드 로벨) — 편지를 못 받아 슬픈 두꺼비에게 개구리가 편지를 써서 달팽이에게 부탁해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_basic#1','kor',2,1,'u8','L07','g2_1_kor_u8_L07_basic','lesson_basic','K2-1-u8-C9',1,'mc','auto','엄마가 외출하기 전에 오누이에게 하신 말씀은?',ARRAY['K2-1-u8-X03']::text[],false,'{"seq":1,"concept":"K2-1-u8-C9","difficulty":1,"kind":"mc","stem":"엄마가 외출하기 전에 오누이에게 하신 말씀은?","options":[{"t":"모르는 사람이 오면 절대 문을 열어 주지 말라고 하셨어요","correct":true},{"t":"잔칫집에 같이 가자고 하셨어요","mis":"K2-1-u8-X03"},{"t":"호랑이에게 떡을 주라고 하셨어요","mis":"K2-1-u8-X03"}],"explanation":["당부예요.","266쪽 (1)이에요.","예시 답안이에요."],"asset":{"type":"passage","lines":["엄마가 잔칫집에 가시며 모르는 사람이 오면 절대 문을 열어 주지 말라고 하셨어요.","고개에서 엄마를 잡아먹은 호랑이가 엄마인 척 「엄마가 왔단다.」 하고 찾아왔어요.","나무 위로 도망친 똘이는 호랑이에게 손에 기름을 바르고 올라오라고 했어요.","오누이는 하늘에서 내려온 동아줄을 타고 올라가 해와 달이 되었고, 썩은 동아줄을 잡은 호랑이는 떨어졌어요."],"title":"『국어』 264~267쪽 「해와 달이 된 오누이」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_basic#2','kor',2,1,'u8','L07','g2_1_kor_u8_L07_basic','lesson_basic','K2-1-u8-C9',1,'mc','auto','「해와 달이 된 오누이」는 어떤 인형극으로 보았나요?',ARRAY['K2-1-u8-X03']::text[],false,'{"seq":2,"concept":"K2-1-u8-C9","difficulty":1,"kind":"mc","stem":"「해와 달이 된 오누이」는 어떤 인형극으로 보았나요?","options":[{"t":"그림자 인형극","correct":true},{"t":"손가락 인형극","mis":"K2-1-u8-X03"},{"t":"탈 인형극","mis":"K2-1-u8-X03"}],"explanation":["그림자 인형극이에요.","264쪽 도우미예요.","인형극이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
