INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_basic#5','kor',2,1,'u8','L07','g2_1_kor_u8_L07_basic','lesson_basic','K2-1-u8-C9',2,'mc','auto','호랑이가 나무에 올라가는 방법을 묻자 똘이는 뭐라고 했나요?',ARRAY['K2-1-u8-X03']::text[],false,'{"seq":5,"concept":"K2-1-u8-C9","difficulty":2,"kind":"mc","stem":"호랑이가 나무에 올라가는 방법을 묻자 똘이는 뭐라고 했나요?","options":[{"t":"손에 기름을 바르고 올라오라고 했어요","correct":true},{"t":"사다리를 타라고 했어요","mis":"K2-1-u8-X03"},{"t":"도끼로 찍으라고 했어요","mis":"K2-1-u8-X03"}],"explanation":["기름이에요.","266쪽 (2)예요.","예시 답안이에요."],"asset":{"type":"passage","lines":["엄마가 잔칫집에 가시며 모르는 사람이 오면 절대 문을 열어 주지 말라고 하셨어요.","고개에서 엄마를 잡아먹은 호랑이가 엄마인 척 「엄마가 왔단다.」 하고 찾아왔어요.","나무 위로 도망친 똘이는 호랑이에게 손에 기름을 바르고 올라오라고 했어요.","오누이는 하늘에서 내려온 동아줄을 타고 올라가 해와 달이 되었고, 썩은 동아줄을 잡은 호랑이는 떨어졌어요."],"title":"『국어』 264~267쪽 「해와 달이 된 오누이」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
