INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_challenge#7','kor',2,1,'u8','L07','g2_1_kor_u8_L07_challenge','lesson_challenge','K2-1-u8-C9',3,'mc','auto','인형극과 이야기책을 견주어 볼 때 알맞은 것은?',ARRAY['K2-1-u8-X10']::text[],false,'{"seq":7,"concept":"K2-1-u8-C9","difficulty":3,"kind":"mc","stem":"인형극과 이야기책을 견주어 볼 때 알맞은 것은?","options":[{"t":"비슷한 점과 다른 점, 느낌이 어떻게 다른지 이야기해요","correct":true},{"t":"둘 중 하나만 맞다고 해요","mis":"K2-1-u8-X10"},{"t":"견주지 않아요","mis":"K2-1-u8-X10"}],"explanation":["견주어 봐요.","지도서 333쪽이에요.","반응 심화하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_challenge#8','kor',2,1,'u8','L07','g2_1_kor_u8_L07_challenge','lesson_challenge','K2-1-u8-C9',4,'sa','auto','오누이가 타고 하늘로 올라간 것을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-1-u8-C9","difficulty":4,"kind":"sa","stem":"오누이가 타고 하늘로 올라간 것을 세 글자로 쓰세요.","answer":["동아줄"],"explanation":["동아줄이에요.","266쪽이에요.","인형극이에요."],"asset":{"type":"passage","lines":["엄마가 잔칫집에 가시며 모르는 사람이 오면 절대 문을 열어 주지 말라고 하셨어요.","고개에서 엄마를 잡아먹은 호랑이가 엄마인 척 「엄마가 왔단다.」 하고 찾아왔어요.","나무 위로 도망친 똘이는 호랑이에게 손에 기름을 바르고 올라오라고 했어요.","오누이는 하늘에서 내려온 동아줄을 타고 올라가 해와 달이 되었고, 썩은 동아줄을 잡은 호랑이는 떨어졌어요."],"title":"『국어』 264~267쪽 「해와 달이 된 오누이」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_challenge#9','kor',2,1,'u8','L07','g2_1_kor_u8_L07_challenge','lesson_challenge','K2-1-u8-C10',4,'essay','teacher','267쪽 — 「해와 달이 된 오누이」에서 기억에 남는 장면을 골라 그 장면에서 인물의 마음을 짐작해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u8-C10","difficulty":4,"kind":"essay","stem":"267쪽 — 「해와 달이 된 오누이」에서 기억에 남는 장면을 골라 그 장면에서 인물의 마음을 짐작해 쓰세요.","answer_guide":{"answer":"예: 호랑이가 갑자기 나타났을 때 — 엄마는 놀랍기도 하고 무섭기도 했을 것이다.","scoring_points":["기억에 남는 장면을 골랐어요","인물의 마음을 짐작해 썼어요"]},"explanation":["인물의 마음이에요.","267쪽이에요.","예시 답안이에요."],"asset":{"type":"passage","lines":["엄마가 잔칫집에 가시며 모르는 사람이 오면 절대 문을 열어 주지 말라고 하셨어요.","고개에서 엄마를 잡아먹은 호랑이가 엄마인 척 「엄마가 왔단다.」 하고 찾아왔어요.","나무 위로 도망친 똘이는 호랑이에게 손에 기름을 바르고 올라오라고 했어요.","오누이는 하늘에서 내려온 동아줄을 타고 올라가 해와 달이 되었고, 썩은 동아줄을 잡은 호랑이는 떨어졌어요."],"title":"『국어』 264~267쪽 「해와 달이 된 오누이」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L07_challenge#10','kor',2,1,'u8','L07','g2_1_kor_u8_L07_challenge','lesson_challenge','K2-1-u8-C10',4,'essay','teacher','「해와 달이 된 오누이」 인형극을 보고 든 생각이나 느낌을 장면과 까닭을 넣어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u8-C10","difficulty":4,"kind":"essay","stem":"「해와 달이 된 오누이」 인형극을 보고 든 생각이나 느낌을 장면과 까닭을 넣어 쓰세요.","answer_guide":{"answer":"예: 순이가 호랑이에게 나무 오르는 방법을 알려 줄 때 답답했다. 호랑이가 금방 따라 올라올 것 같았기 때문이다.","scoring_points":["장면을 썼어요","생각이나 느낌과 까닭을 썼어요"]},"explanation":["감상이에요.","지도서 333쪽이에요.","반응 명료화예요."],"asset":{"type":"passage","lines":["엄마가 잔칫집에 가시며 모르는 사람이 오면 절대 문을 열어 주지 말라고 하셨어요.","고개에서 엄마를 잡아먹은 호랑이가 엄마인 척 「엄마가 왔단다.」 하고 찾아왔어요.","나무 위로 도망친 똘이는 호랑이에게 손에 기름을 바르고 올라오라고 했어요.","오누이는 하늘에서 내려온 동아줄을 타고 올라가 해와 달이 되었고, 썩은 동아줄을 잡은 호랑이는 떨어졌어요."],"title":"『국어』 264~267쪽 「해와 달이 된 오누이」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_basic#1','kor',2,1,'u8','L09','g2_1_kor_u8_L09_basic','lesson_basic','K2-1-u8-C11',1,'mc','auto','형이 볏단을 아우에게 주려고 한 까닭은?',ARRAY['K2-1-u8-X14']::text[],false,'{"seq":1,"concept":"K2-1-u8-C11","difficulty":1,"kind":"mc","stem":"형이 볏단을 아우에게 주려고 한 까닭은?","options":[{"t":"아우에게 볏단이 더 필요하다고 생각해서","correct":true},{"t":"볏단이 무거워서","mis":"K2-1-u8-X14"},{"t":"아우가 졸라서","mis":"K2-1-u8-X14"}],"explanation":["아우를 아껴요.","269쪽 (1)이에요.","예시 답안이에요."],"asset":{"type":"passage","lines":["형은 아우에게 볏단이 더 필요할 거라며 밤에 몰래 아우의 볏가리에 볏단을 옮겼어요.","아우도 형님에게 더 필요하다며 몰래 형의 볏가리에 볏단을 옮겼어요.","아침마다 볏단이 그대로라 형제는 어리둥절했어요.","어느 밤 길에서 마주친 형제는 서로의 마음을 알고 얼싸안았어요."],"title":"『국어』 268~271쪽 「의좋은 형제」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_basic#2','kor',2,1,'u8','L09','g2_1_kor_u8_L09_basic','lesson_basic','K2-1-u8-C11',1,'mc','auto','볏단이 그대로인 것을 안 형제는 어떻게 생각했나요?',ARRAY['K2-1-u8-X03']::text[],false,'{"seq":2,"concept":"K2-1-u8-C11","difficulty":1,"kind":"mc","stem":"볏단이 그대로인 것을 안 형제는 어떻게 생각했나요?","options":[{"t":"어찌 된 일인지 몰라 어리둥절해했어요","correct":true},{"t":"화를 냈어요","mis":"K2-1-u8-X03"},{"t":"아무렇지 않았어요","mis":"K2-1-u8-X03"}],"explanation":["어리둥절해요.","269쪽 (2)예요.","예시 답안이에요."],"asset":{"type":"passage","lines":["형은 아우에게 볏단이 더 필요할 거라며 밤에 몰래 아우의 볏가리에 볏단을 옮겼어요.","아우도 형님에게 더 필요하다며 몰래 형의 볏가리에 볏단을 옮겼어요.","아침마다 볏단이 그대로라 형제는 어리둥절했어요.","어느 밤 길에서 마주친 형제는 서로의 마음을 알고 얼싸안았어요."],"title":"『국어』 268~271쪽 「의좋은 형제」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
