INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_challenge#7','kor',2,1,'u8','L09','g2_1_kor_u8_L09_challenge','lesson_challenge','K2-1-u8-C11',3,'mc','auto','인물의 말과 행동을 따라 해 보면 좋은 점은?',ARRAY['K2-1-u8-X12']::text[],false,'{"seq":7,"concept":"K2-1-u8-C11","difficulty":3,"kind":"mc","stem":"인물의 말과 행동을 따라 해 보면 좋은 점은?","options":[{"t":"인물의 마음이 더 잘 느껴져요","correct":true},{"t":"인형극을 안 봐도 돼요","mis":"K2-1-u8-X12"},{"t":"대사를 바꿔도 돼요","mis":"K2-1-u8-X12"}],"explanation":["마음이 느껴져요.","271쪽이에요.","따라 하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_challenge#8','kor',2,1,'u8','L09','g2_1_kor_u8_L09_challenge','lesson_challenge','K2-1-u8-C11',4,'sa','auto','형제가 서로의 볏가리에 몰래 옮긴 것을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-1-u8-C11","difficulty":4,"kind":"sa","stem":"형제가 서로의 볏가리에 몰래 옮긴 것을 두 글자로 쓰세요.","answer":["볏단"],"explanation":["볏단이에요.","269쪽이에요.","이야기예요."],"asset":{"type":"passage","lines":["형은 아우에게 볏단이 더 필요할 거라며 밤에 몰래 아우의 볏가리에 볏단을 옮겼어요.","아우도 형님에게 더 필요하다며 몰래 형의 볏가리에 볏단을 옮겼어요.","아침마다 볏단이 그대로라 형제는 어리둥절했어요.","어느 밤 길에서 마주친 형제는 서로의 마음을 알고 얼싸안았어요."],"title":"『국어』 268~271쪽 「의좋은 형제」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_challenge#9','kor',2,1,'u8','L09','g2_1_kor_u8_L09_challenge','lesson_challenge','K2-1-u8-C11',4,'essay','teacher','273쪽 — 「의좋은 형제」의 형이나 아우에게 나의 생각이나 느낌을 전하는 편지를 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u8-C11","difficulty":4,"kind":"essay","stem":"273쪽 — 「의좋은 형제」의 형이나 아우에게 나의 생각이나 느낌을 전하는 편지를 쓰세요.","answer_guide":{"answer":"예: 성실한 아우님께 — 형님에게 농사짓는 법을 열심히 배우는 모습이 멋있었어요. 저도 성실하게 노력하고 싶어요.","scoring_points":["형이나 아우에게 썼어요","생각이나 느낌과 까닭을 썼어요"]},"explanation":["인물에게 편지예요.","273쪽이에요.","예시 답안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L09_challenge#10','kor',2,1,'u8','L09','g2_1_kor_u8_L09_challenge','lesson_challenge','K2-1-u8-C8',4,'essay','teacher','「의좋은 형제」에서 가장 기억에 남는 장면과 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u8-C8","difficulty":4,"kind":"essay","stem":"「의좋은 형제」에서 가장 기억에 남는 장면과 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 형제가 서로 마주쳐 얼싸안는 장면 — 서로를 아끼는 마음이 느껴져 가슴이 따뜻해졌기 때문이다.","scoring_points":["기억에 남는 장면을 썼어요","까닭을 썼어요"]},"explanation":["감상이에요.","273쪽 (1)이에요.","예시 답안이에요."],"asset":{"type":"passage","lines":["형은 아우에게 볏단이 더 필요할 거라며 밤에 몰래 아우의 볏가리에 볏단을 옮겼어요.","아우도 형님에게 더 필요하다며 몰래 형의 볏가리에 볏단을 옮겼어요.","아침마다 볏단이 그대로라 형제는 어리둥절했어요.","어느 밤 길에서 마주친 형제는 서로의 마음을 알고 얼싸안았어요."],"title":"『국어』 268~271쪽 「의좋은 형제」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
