INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_L12_challenge#10','kor',2,1,'u8','L12','g2_1_kor_u8_L12_challenge','lesson_challenge','K2-1-u8-C12',4,'essay','teacher','모둠에서 인형극으로 꾸미고 싶은 장면 하나와 필요한 인물, 그 장면에서 드러내고 싶은 인물의 마음을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u8-C12","difficulty":4,"kind":"essay","stem":"모둠에서 인형극으로 꾸미고 싶은 장면 하나와 필요한 인물, 그 장면에서 드러내고 싶은 인물의 마음을 쓰세요.","answer_guide":{"answer":"예: 「해와 달이 된 오누이」의 동아줄 장면 — 똘이, 순이, 호랑이 — 오누이의 간절한 마음과 기쁜 마음","scoring_points":["장면과 인물을 썼어요","드러내고 싶은 마음을 썼어요"]},"explanation":["인형극 준비예요.","274쪽이에요.","지도서 339쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
