INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#2','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C3',1,'mc','auto','「신호」에서 두 친구가 만난 곳은?',ARRAY['K2-1-u8-X03']::text[],false,'{"seq":2,"concept":"K2-1-u8-C3","difficulty":1,"kind":"mc","stem":"「신호」에서 두 친구가 만난 곳은?","options":[{"t":"건널목","correct":true},{"t":"교실","mis":"K2-1-u8-X03"},{"t":"놀이터","mis":"K2-1-u8-X03"}],"explanation":["건널목이에요.","252쪽이에요.","예시예요."],"asset":{"type":"scene","icon":"🚦","text":"「신호」(장세정) — 건널목 빨간불 앞에서 두 친구가 빙긋 웃고 까딱하고 휘휘 흔들고 폴짝폴짝 뛰며 신호를 주고받아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#3','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C6',1,'mc','auto','두꺼비가 하루 가운데 가장 슬플 때는?',ARRAY['K2-1-u8-X03']::text[],false,'{"seq":3,"concept":"K2-1-u8-C6","difficulty":1,"kind":"mc","stem":"두꺼비가 하루 가운데 가장 슬플 때는?","options":[{"t":"편지 오기를 기다리는 때","correct":true},{"t":"잠자리에 드는 때","mis":"K2-1-u8-X03"},{"t":"밥 먹는 때","mis":"K2-1-u8-X03"}],"explanation":["편지 기다릴 때예요.","260쪽이에요.","예시예요."],"asset":{"type":"scene","icon":"✉️","text":"「편지」(아놀드 로벨) — 편지를 못 받아 슬픈 두꺼비에게 개구리가 편지를 써서 달팽이에게 부탁해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#4','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C9',1,'mc','auto','엄마가 오누이에게 하신 말씀은?',ARRAY['K2-1-u8-X03']::text[],false,'{"seq":4,"concept":"K2-1-u8-C9","difficulty":1,"kind":"mc","stem":"엄마가 오누이에게 하신 말씀은?","options":[{"t":"모르는 사람이 오면 문을 열어 주지 말라고 하셨어요","correct":true},{"t":"잔칫집에 같이 가자","mis":"K2-1-u8-X03"},{"t":"호랑이에게 떡을 주라","mis":"K2-1-u8-X03"}],"explanation":["당부예요.","266쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["엄마가 잔칫집에 가시며 모르는 사람이 오면 절대 문을 열어 주지 말라고 하셨어요.","고개에서 엄마를 잡아먹은 호랑이가 엄마인 척 「엄마가 왔단다.」 하고 찾아왔어요.","나무 위로 도망친 똘이는 호랑이에게 손에 기름을 바르고 올라오라고 했어요.","오누이는 하늘에서 내려온 동아줄을 타고 올라가 해와 달이 되었고, 썩은 동아줄을 잡은 호랑이는 떨어졌어요."],"title":"『국어』 264~267쪽 「해와 달이 된 오누이」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#5','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C11',1,'mc','auto','형이 볏단을 아우에게 주려고 한 까닭은?',ARRAY['K2-1-u8-X14']::text[],false,'{"seq":5,"concept":"K2-1-u8-C11","difficulty":1,"kind":"mc","stem":"형이 볏단을 아우에게 주려고 한 까닭은?","options":[{"t":"아우에게 볏단이 더 필요하다고 생각해서","correct":true},{"t":"무거워서","mis":"K2-1-u8-X14"},{"t":"아우가 졸라서","mis":"K2-1-u8-X14"}],"explanation":["아우를 아껴요.","269쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["형은 아우에게 볏단이 더 필요할 거라며 밤에 몰래 아우의 볏가리에 볏단을 옮겼어요.","아우도 형님에게 더 필요하다며 몰래 형의 볏가리에 볏단을 옮겼어요.","아침마다 볏단이 그대로라 형제는 어리둥절했어요.","어느 밤 길에서 마주친 형제는 서로의 마음을 알고 얼싸안았어요."],"title":"『국어』 268~271쪽 「의좋은 형제」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
