INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#12','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C9',2,'mc','auto','똘이가 호랑이에게 나무 오르는 방법으로 말한 것은?',ARRAY['K2-1-u8-X03']::text[],false,'{"seq":12,"concept":"K2-1-u8-C9","difficulty":2,"kind":"mc","stem":"똘이가 호랑이에게 나무 오르는 방법으로 말한 것은?","options":[{"t":"손에 기름을 바르고 올라오라고 했어요","correct":true},{"t":"사다리를 타라고","mis":"K2-1-u8-X03"},{"t":"도끼로 찍으라고","mis":"K2-1-u8-X03"}],"explanation":["기름이에요.","266쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["엄마가 잔칫집에 가시며 모르는 사람이 오면 절대 문을 열어 주지 말라고 하셨어요.","고개에서 엄마를 잡아먹은 호랑이가 엄마인 척 「엄마가 왔단다.」 하고 찾아왔어요.","나무 위로 도망친 똘이는 호랑이에게 손에 기름을 바르고 올라오라고 했어요.","오누이는 하늘에서 내려온 동아줄을 타고 올라가 해와 달이 되었고, 썩은 동아줄을 잡은 호랑이는 떨어졌어요."],"title":"『국어』 264~267쪽 「해와 달이 된 오누이」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#13','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C11',2,'mc','auto','볏단을 가져다준 사람을 안 형제의 마음은?',ARRAY['K2-1-u8-X14']::text[],false,'{"seq":13,"concept":"K2-1-u8-C11","difficulty":2,"kind":"mc","stem":"볏단을 가져다준 사람을 안 형제의 마음은?","options":[{"t":"서로를 위하는 마음에 감동한 마음","correct":true},{"t":"억울한 마음","mis":"K2-1-u8-X14"},{"t":"귀찮은 마음","mis":"K2-1-u8-X14"}],"explanation":["감동했어요.","269쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["형은 아우에게 볏단이 더 필요할 거라며 밤에 몰래 아우의 볏가리에 볏단을 옮겼어요.","아우도 형님에게 더 필요하다며 몰래 형의 볏가리에 볏단을 옮겼어요.","아침마다 볏단이 그대로라 형제는 어리둥절했어요.","어느 밤 길에서 마주친 형제는 서로의 마음을 알고 얼싸안았어요."],"title":"『국어』 268~271쪽 「의좋은 형제」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
