INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#19','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C3',3,'ox','auto','「신호」에는 「반갑다」는 말이 없으므로 두 친구의 마음을 알 수 없다.',ARRAY['K2-1-u8-X04']::text[],false,'{"seq":19,"concept":"K2-1-u8-C3","difficulty":3,"kind":"ox","stem":"「신호」에는 「반갑다」는 말이 없으므로 두 친구의 마음을 알 수 없다.","answer":"X","reason_options":[{"t":"웃고 까딱하고 폴짝폴짝 뛰는 행동에서 반가운 마음을 짐작할 수 있어서","correct":true},{"t":"마음은 낱말로만 알 수 있어서","mis":"K2-1-u8-X04"}],"mis":"K2-1-u8-X04","explanation":["행동 속 마음이에요.","지도서 323쪽이에요.","작품 읽기예요."],"asset":{"type":"scene","icon":"🚦","text":"「신호」(장세정) — 건널목 빨간불 앞에서 두 친구가 빙긋 웃고 까딱하고 휘휘 흔들고 폴짝폴짝 뛰며 신호를 주고받아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#20','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C7',3,'mc','auto','개구리가 말로 하지 않고 편지를 쓴 까닭은?',ARRAY['K2-1-u8-X14']::text[],false,'{"seq":20,"concept":"K2-1-u8-C7","difficulty":3,"kind":"mc","stem":"개구리가 말로 하지 않고 편지를 쓴 까닭은?","options":[{"t":"편지를 받아 보고 싶은 두꺼비의 바람을 들어주고 싶어서","correct":true},{"t":"말하기 귀찮아서","mis":"K2-1-u8-X14"},{"t":"싸워서","mis":"K2-1-u8-X14"}],"explanation":["바람을 들어줘요.","지도서 328쪽이에요.","깊이 있는 감상이에요."],"asset":{"type":"scene","icon":"✉️","text":"「편지」(아놀드 로벨) — 편지를 못 받아 슬픈 두꺼비에게 개구리가 편지를 써서 달팽이에게 부탁해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
