INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#22','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C5',3,'mc','auto','시를 낭송할 때 가장 중요한 것은?',ARRAY['K2-1-u8-X06']::text[],false,'{"seq":22,"concept":"K2-1-u8-C5","difficulty":3,"kind":"mc","stem":"시를 낭송할 때 가장 중요한 것은?","options":[{"t":"시에 대한 생각이나 느낌을 담아 즐겁게 표현하는 것","correct":true},{"t":"가장 빠르게 읽는 것","mis":"K2-1-u8-X06"},{"t":"가장 크게 읽는 것","mis":"K2-1-u8-X06"}],"explanation":["감상 표현이에요.","지도서 319쪽이에요.","유의 사항이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#23','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C3',4,'sa','auto','「신호」에서 두 친구가 마주친 곳을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u8-C3","difficulty":4,"kind":"sa","stem":"「신호」에서 두 친구가 마주친 곳을 세 글자로 쓰세요.","answer":["건널목"],"explanation":["건널목이에요.","252쪽이에요.","시예요."],"asset":{"type":"scene","icon":"🚦","text":"「신호」(장세정) — 건널목 빨간불 앞에서 두 친구가 빙긋 웃고 까딱하고 휘휘 흔들고 폴짝폴짝 뛰며 신호를 주고받아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#24','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C7',4,'essay','teacher','지도서 344~345쪽 평가 — 「편지」의 두꺼비라면 편지를 받았을 때 어떤 마음이 들었을지 「왜냐하면」을 넣어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u8-C7","difficulty":4,"kind":"essay","stem":"지도서 344~345쪽 평가 — 「편지」의 두꺼비라면 편지를 받았을 때 어떤 마음이 들었을지 「왜냐하면」을 넣어 쓰세요.","answer_guide":{"answer":"예: 제가 두꺼비라면 무척 기쁘고 고마운 마음이 들었을 것입니다. 왜냐하면 가장 친한 친구가 나를 위해 편지를 써 주었기 때문입니다.","scoring_points":["인물이 되어 마음을 썼어요","「왜냐하면」으로 까닭을 썼어요"]},"explanation":["평가 자료 1이에요.","지도서 345쪽이에요.","인물의 마음이에요."],"asset":{"type":"scene","icon":"✉️","text":"「편지」(아놀드 로벨) — 편지를 못 받아 슬픈 두꺼비에게 개구리가 편지를 써서 달팽이에게 부탁해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_a#25','kor',2,1,'u8','','g2_1_kor_u8_review_a','unit_review','K2-1-u8-C13',4,'essay','teacher','지도서 346~347쪽 평가 — 「팥죽 할멈과 호랑이」 대본을 읽고 자신의 생각이나 느낌을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u8-C13","difficulty":4,"kind":"essay","stem":"지도서 346~347쪽 평가 — 「팥죽 할멈과 호랑이」 대본을 읽고 자신의 생각이나 느낌을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 알밤과 송곳, 멍석, 지게가 할머니를 도와주는 장면이 재미있었다. 작은 것들이 힘을 합쳐 호랑이를 물리쳐서 통쾌했다.","scoring_points":["생각이나 느낌을 썼어요","까닭을 썼어요"]},"explanation":["평가 자료 2예요.","지도서 347쪽이에요.","감상이에요."],"asset":{"type":"speech","turns":[{"who":"호랑이","text":"어흥, 팥죽도 먹고 할머니도 잡아먹으러 왔다."},{"who":"해설","text":"알밤이 뻥 터지며 호랑이 눈에 박치기를 했어. 송곳이 엉덩이를 쿡 찔렀어."},{"who":"해설","text":"멍석이 호랑이를 둘둘 말고, 지게가 강물에 풍덩 던져 버렸어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
