INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#3','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C6',1,'mc','auto','개구리가 달팽이에게 한 부탁은?',ARRAY['K2-1-u8-X03']::text[],false,'{"seq":3,"concept":"K2-1-u8-C6","difficulty":1,"kind":"mc","stem":"개구리가 달팽이에게 한 부탁은?","options":[{"t":"두꺼비에게 편지를 전해 달라는 부탁","correct":true},{"t":"함께 놀자는 부탁","mis":"K2-1-u8-X03"},{"t":"집을 지켜 달라는 부탁","mis":"K2-1-u8-X03"}],"explanation":["편지 전하기예요.","260쪽이에요.","예시예요."],"asset":{"type":"scene","icon":"✉️","text":"「편지」(아놀드 로벨) — 편지를 못 받아 슬픈 두꺼비에게 개구리가 편지를 써서 달팽이에게 부탁해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#4','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C9',1,'mc','auto','「해와 달이 된 오누이」는 어떤 인형극이었나요?',ARRAY['K2-1-u8-X03']::text[],false,'{"seq":4,"concept":"K2-1-u8-C9","difficulty":1,"kind":"mc","stem":"「해와 달이 된 오누이」는 어떤 인형극이었나요?","options":[{"t":"그림자 인형극","correct":true},{"t":"손가락 인형극","mis":"K2-1-u8-X03"},{"t":"탈 인형극","mis":"K2-1-u8-X03"}],"explanation":["그림자 인형극이에요.","264쪽이에요.","도우미예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#5','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C11',1,'mc','auto','볏단이 그대로인 것을 안 형제는?',ARRAY['K2-1-u8-X03']::text[],false,'{"seq":5,"concept":"K2-1-u8-C11","difficulty":1,"kind":"mc","stem":"볏단이 그대로인 것을 안 형제는?","options":[{"t":"어리둥절해했어요","correct":true},{"t":"화를 냈어요","mis":"K2-1-u8-X03"},{"t":"아무렇지 않았어요","mis":"K2-1-u8-X03"}],"explanation":["어리둥절해요.","269쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["형은 아우에게 볏단이 더 필요할 거라며 밤에 몰래 아우의 볏가리에 볏단을 옮겼어요.","아우도 형님에게 더 필요하다며 몰래 형의 볏가리에 볏단을 옮겼어요.","아침마다 볏단이 그대로라 형제는 어리둥절했어요.","어느 밤 길에서 마주친 형제는 서로의 마음을 알고 얼싸안았어요."],"title":"『국어』 268~271쪽 「의좋은 형제」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
