INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#7','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C5',1,'mc','auto','몸짓으로 표현하며 낭송할 때 알맞은 것은?',ARRAY['K2-1-u8-X06']::text[],false,'{"seq":7,"concept":"K2-1-u8-C5","difficulty":1,"kind":"mc","stem":"몸짓으로 표현하며 낭송할 때 알맞은 것은?","options":[{"t":"떠오르는 장면을 몸짓으로 나타내며 읽어요","correct":true},{"t":"가만히 서서 읽어요","mis":"K2-1-u8-X06"},{"t":"춤만 춰요","mis":"K2-1-u8-X06"}],"explanation":["몸짓 낭송이에요.","253쪽이에요.","여러 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#8','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C10',1,'mc','auto','「저희를 살려 주세요!」라고 빈 오누이의 마음은?',ARRAY['K2-1-u8-X15']::text[],false,'{"seq":8,"concept":"K2-1-u8-C10","difficulty":1,"kind":"mc","stem":"「저희를 살려 주세요!」라고 빈 오누이의 마음은?","options":[{"t":"다급하고 간절한 마음","correct":true},{"t":"느긋한 마음","mis":"K2-1-u8-X15"},{"t":"장난스러운 마음","mis":"K2-1-u8-X15"}],"explanation":["간절해요.","지도서 333쪽이에요.","인물의 마음이에요."],"asset":{"type":"passage","lines":["엄마가 잔칫집에 가시며 모르는 사람이 오면 절대 문을 열어 주지 말라고 하셨어요.","고개에서 엄마를 잡아먹은 호랑이가 엄마인 척 「엄마가 왔단다.」 하고 찾아왔어요.","나무 위로 도망친 똘이는 호랑이에게 손에 기름을 바르고 올라오라고 했어요.","오누이는 하늘에서 내려온 동아줄을 타고 올라가 해와 달이 되었고, 썩은 동아줄을 잡은 호랑이는 떨어졌어요."],"title":"『국어』 264~267쪽 「해와 달이 된 오누이」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
