INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#10','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C3',2,'mc','auto','「신호」에서 두 친구의 행동에서 느껴지는 마음은?',ARRAY['K2-1-u8-X04']::text[],false,'{"seq":10,"concept":"K2-1-u8-C3","difficulty":2,"kind":"mc","stem":"「신호」에서 두 친구의 행동에서 느껴지는 마음은?","options":[{"t":"반갑고 즐거운 마음","correct":true},{"t":"미운 마음","mis":"K2-1-u8-X04"},{"t":"지루한 마음","mis":"K2-1-u8-X04"}],"explanation":["반가워요.","지도서 323쪽이에요.","행동 속 마음이에요."],"asset":{"type":"scene","icon":"🚦","text":"「신호」(장세정) — 건널목 빨간불 앞에서 두 친구가 빙긋 웃고 까딱하고 휘휘 흔들고 폴짝폴짝 뛰며 신호를 주고받아요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#11','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C7',2,'mc','auto','개구리가 서둘러 집에 가서 편지를 쓴 마음은?',ARRAY['K2-1-u8-X14']::text[],false,'{"seq":11,"concept":"K2-1-u8-C7","difficulty":2,"kind":"mc","stem":"개구리가 서둘러 집에 가서 편지를 쓴 마음은?","options":[{"t":"두꺼비를 기쁘게 해 주고 싶은 마음","correct":true},{"t":"귀찮은 마음","mis":"K2-1-u8-X14"},{"t":"화난 마음","mis":"K2-1-u8-X14"}],"explanation":["기쁘게 해 주고 싶어요.","261쪽이에요.","예시예요."],"asset":{"type":"scene","icon":"✉️","text":"「편지」(아놀드 로벨) — 편지를 못 받아 슬픈 두꺼비에게 개구리가 편지를 써서 달팽이에게 부탁해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#12','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C9',2,'mc','auto','오누이가 하늘로 올라가자 호랑이는?',ARRAY['K2-1-u8-X03']::text[],false,'{"seq":12,"concept":"K2-1-u8-C9","difficulty":2,"kind":"mc","stem":"오누이가 하늘로 올라가자 호랑이는?","options":[{"t":"자신에게도 동아줄을 내려 달라고 빌었어요","correct":true},{"t":"집으로 갔어요","mis":"K2-1-u8-X03"},{"t":"사과했어요","mis":"K2-1-u8-X03"}],"explanation":["빌었어요.","266쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["엄마가 잔칫집에 가시며 모르는 사람이 오면 절대 문을 열어 주지 말라고 하셨어요.","고개에서 엄마를 잡아먹은 호랑이가 엄마인 척 「엄마가 왔단다.」 하고 찾아왔어요.","나무 위로 도망친 똘이는 호랑이에게 손에 기름을 바르고 올라오라고 했어요.","오누이는 하늘에서 내려온 동아줄을 타고 올라가 해와 달이 되었고, 썩은 동아줄을 잡은 호랑이는 떨어졌어요."],"title":"『국어』 264~267쪽 「해와 달이 된 오누이」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#13','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C11',2,'mc','auto','「의좋은 형제」의 차례로 알맞은 것은?',ARRAY['K2-1-u8-X07']::text[],false,'{"seq":13,"concept":"K2-1-u8-C11","difficulty":2,"kind":"mc","stem":"「의좋은 형제」의 차례로 알맞은 것은?","options":[{"t":"벼를 벰 → 몰래 볏단을 옮김 → 어리둥절함 → 얼싸안음","correct":true},{"t":"얼싸안음 → 벼를 벰 → 옮김","mis":"K2-1-u8-X07"},{"t":"어리둥절함 → 벼를 벰 → 다툼","mis":"K2-1-u8-X07"}],"explanation":["차례예요.","269쪽이에요.","글과 연결하기예요."],"asset":{"type":"passage","lines":["형은 아우에게 볏단이 더 필요할 거라며 밤에 몰래 아우의 볏가리에 볏단을 옮겼어요.","아우도 형님에게 더 필요하다며 몰래 형의 볏가리에 볏단을 옮겼어요.","아침마다 볏단이 그대로라 형제는 어리둥절했어요.","어느 밤 길에서 마주친 형제는 서로의 마음을 알고 얼싸안았어요."],"title":"『국어』 268~271쪽 「의좋은 형제」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#14','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C13',2,'mc','auto','느낀 점을 발표하는 방법이 아닌 것은?',ARRAY['K2-1-u8-X01']::text[],false,'{"seq":14,"concept":"K2-1-u8-C13","difficulty":2,"kind":"mc","stem":"느낀 점을 발표하는 방법이 아닌 것은?","options":[{"t":"「그냥 「재미있다」고 말하면 돼.」","correct":true},{"t":"「기억에 남는 장면과 까닭을 생각해 봐.」","mis":"K2-1-u8-X01"},{"t":"「인물에게 하고 싶은 말을 떠올려 봐.」","mis":"K2-1-u8-X01"}],"explanation":["까닭과 함께요.","276쪽이에요.","생쥐 길 찾기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
