INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#16','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C7',2,'match','auto','「편지」 인물의 말이나 행동과 마음을 이어 보세요.','{}'::text[],false,'{"seq":16,"concept":"K2-1-u8-C7","difficulty":2,"kind":"match","stem":"「편지」 인물의 말이나 행동과 마음을 이어 보세요.","pairs":[{"l":"「나는 편지를 한 번도 못 받았거든.」","r":"속상한 마음"},{"l":"서둘러 집에 가서 편지를 썼어요","r":"기쁘게 해 주고 싶은 마음"},{"l":"「와, 정말로 멋진 편지다.」","r":"기뻐하며 감탄하는 마음"}],"mis":"K2-1-u8-X14","explanation":["말·행동과 마음이에요.","261쪽이에요.","예시예요."],"asset":{"type":"scene","icon":"✉️","text":"「편지」(아놀드 로벨) — 편지를 못 받아 슬픈 두꺼비에게 개구리가 편지를 써서 달팽이에게 부탁해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
