INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#19','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C10',3,'ox','auto','호랑이 인형이 무섭게 생겼으니 생김새만 보면 마음을 다 알 수 있다.',ARRAY['K2-1-u8-X08']::text[],false,'{"seq":19,"concept":"K2-1-u8-C10","difficulty":3,"kind":"ox","stem":"호랑이 인형이 무섭게 생겼으니 생김새만 보면 마음을 다 알 수 있다.","answer":"X","reason_options":[{"t":"말과 행동, 목소리를 살펴야 마음을 짐작할 수 있어서","correct":true},{"t":"생김새가 곧 마음이라서","mis":"K2-1-u8-X08"}],"mis":"K2-1-u8-X08","explanation":["말·행동·목소리예요.","267쪽이에요.","도우미예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#20','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C8',3,'mc','auto','「편지」 감상문으로 알맞은 것은?',ARRAY['K2-1-u8-X01','K2-1-u8-X02']::text[],false,'{"seq":20,"concept":"K2-1-u8-C8","difficulty":3,"kind":"mc","stem":"「편지」 감상문으로 알맞은 것은?","options":[{"t":"「달팽이에게 편지를 부탁한 장면이 기억에 남는다. 덕분에 둘이 오래 행복하게 기다릴 수 있었다.」","correct":true},{"t":"「재미있었다.」","mis":"K2-1-u8-X01"},{"t":"줄거리를 그대로 옮긴 것","mis":"K2-1-u8-X02"}],"explanation":["장면·까닭·생각이에요.","263쪽이에요.","보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#21','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C9',3,'mc','auto','인형극 속 장소가 바뀐 차례로 알맞은 것은?',ARRAY['K2-1-u8-X07']::text[],false,'{"seq":21,"concept":"K2-1-u8-C9","difficulty":3,"kind":"mc","stem":"인형극 속 장소가 바뀐 차례로 알맞은 것은?","options":[{"t":"오누이의 집 → 고개 → 오누이의 집 → 나무 위","correct":true},{"t":"나무 위 → 고개 → 집","mis":"K2-1-u8-X07"},{"t":"고개 → 나무 위 → 잔칫집","mis":"K2-1-u8-X07"}],"explanation":["장소의 차례예요.","지도서 332쪽이에요.","일어난 일이에요."],"asset":{"type":"passage","lines":["엄마가 잔칫집에 가시며 모르는 사람이 오면 절대 문을 열어 주지 말라고 하셨어요.","고개에서 엄마를 잡아먹은 호랑이가 엄마인 척 「엄마가 왔단다.」 하고 찾아왔어요.","나무 위로 도망친 똘이는 호랑이에게 손에 기름을 바르고 올라오라고 했어요.","오누이는 하늘에서 내려온 동아줄을 타고 올라가 해와 달이 되었고, 썩은 동아줄을 잡은 호랑이는 떨어졌어요."],"title":"『국어』 264~267쪽 「해와 달이 된 오누이」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#22','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C4',3,'mc','auto','「까딱」을 알맞게 넣은 문장은?',ARRAY['K2-1-u8-X05']::text[],false,'{"seq":22,"concept":"K2-1-u8-C4","difficulty":3,"kind":"mc","stem":"「까딱」을 알맞게 넣은 문장은?","options":[{"t":"「친구가 인사하자 나도 고개를 까딱했다.」","correct":true},{"t":"「까딱 뛰어 담을 넘었다.」","mis":"K2-1-u8-X05"},{"t":"「물이 까딱 흘렀다.」","mis":"K2-1-u8-X05"}],"explanation":["뜻에 맞아요.","252쪽이에요.","흉내 내는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#23','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C6',4,'sa','auto','두꺼비가 편지를 받기까지 걸린 날을 「○○ 뒤」 꼴로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u8-C6","difficulty":4,"kind":"sa","stem":"두꺼비가 편지를 받기까지 걸린 날을 「○○ 뒤」 꼴로 쓰세요.","answer":["나흘 뒤","나흘뒤","나흘"],"explanation":["나흘 뒤예요.","259쪽이에요.","이야기예요."],"asset":{"type":"scene","icon":"✉️","text":"「편지」(아놀드 로벨) — 편지를 못 받아 슬픈 두꺼비에게 개구리가 편지를 써서 달팽이에게 부탁해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#24','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C8',4,'essay','teacher','「편지」에서 기억에 남는 장면, 그 까닭, 그 장면에 대한 나의 생각을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u8-C8","difficulty":4,"kind":"essay","stem":"「편지」에서 기억에 남는 장면, 그 까닭, 그 장면에 대한 나의 생각을 쓰세요.","answer_guide":{"answer":"예: 두꺼비가 편지를 받고 기뻐하는 장면이 기억에 남는다. 친구의 마음이 담긴 편지라서다. 나도 친구에게 편지를 쓰고 싶다.","scoring_points":["장면과 까닭을 썼어요","내 생각을 썼어요"]},"explanation":["생각이나 느낌 쓰기예요.","263쪽이에요.","보기예요."],"asset":{"type":"scene","icon":"✉️","text":"「편지」(아놀드 로벨) — 편지를 못 받아 슬픈 두꺼비에게 개구리가 편지를 써서 달팽이에게 부탁해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_b#25','kor',2,1,'u8','','g2_1_kor_u8_review_b','unit_review','K2-1-u8-C11',4,'essay','teacher','「의좋은 형제」의 형이나 아우에게 나의 생각이나 느낌을 전하는 편지를 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u8-C11","difficulty":4,"kind":"essay","stem":"「의좋은 형제」의 형이나 아우에게 나의 생각이나 느낌을 전하는 편지를 쓰세요.","answer_guide":{"answer":"예: 마음이 따뜻한 형님께 — 동생을 아끼는 마음이 감동적이었어요. 저도 동생을 더 아껴 주고 싶어요.","scoring_points":["형이나 아우에게 썼어요","생각이나 느낌과 까닭을 썼어요"]},"explanation":["인물에게 편지예요.","273쪽이에요.","예시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
