INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#23','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C9',4,'sa','auto','오누이가 타고 하늘로 올라간 것을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u8-C9","difficulty":4,"kind":"sa","stem":"오누이가 타고 하늘로 올라간 것을 세 글자로 쓰세요.","answer":["동아줄"],"explanation":["동아줄이에요.","266쪽이에요.","인형극이에요."],"asset":{"type":"passage","lines":["엄마가 잔칫집에 가시며 모르는 사람이 오면 절대 문을 열어 주지 말라고 하셨어요.","고개에서 엄마를 잡아먹은 호랑이가 엄마인 척 「엄마가 왔단다.」 하고 찾아왔어요.","나무 위로 도망친 똘이는 호랑이에게 손에 기름을 바르고 올라오라고 했어요.","오누이는 하늘에서 내려온 동아줄을 타고 올라가 해와 달이 되었고, 썩은 동아줄을 잡은 호랑이는 떨어졌어요."],"title":"『국어』 264~267쪽 「해와 달이 된 오누이」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#24','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C10',4,'essay','teacher','「해와 달이 된 오누이」에서 기억에 남는 장면을 골라 인물의 마음을 짐작해 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u8-C10","difficulty":4,"kind":"essay","stem":"「해와 달이 된 오누이」에서 기억에 남는 장면을 골라 인물의 마음을 짐작해 쓰세요.","answer_guide":{"answer":"예: 호랑이가 갑자기 나타났을 때 — 엄마는 놀랍고 무서웠을 것이다.","scoring_points":["장면을 골랐어요","인물의 마음을 짐작해 썼어요"]},"explanation":["인물의 마음이에요.","267쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["엄마가 잔칫집에 가시며 모르는 사람이 오면 절대 문을 열어 주지 말라고 하셨어요.","고개에서 엄마를 잡아먹은 호랑이가 엄마인 척 「엄마가 왔단다.」 하고 찾아왔어요.","나무 위로 도망친 똘이는 호랑이에게 손에 기름을 바르고 올라오라고 했어요.","오누이는 하늘에서 내려온 동아줄을 타고 올라가 해와 달이 되었고, 썩은 동아줄을 잡은 호랑이는 떨어졌어요."],"title":"『국어』 264~267쪽 「해와 달이 된 오누이」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_c#25','kor',2,1,'u8','','g2_1_kor_u8_review_c','unit_review','K2-1-u8-C8',4,'essay','teacher','「의좋은 형제」에서 가장 기억에 남는 장면과 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u8-C8","difficulty":4,"kind":"essay","stem":"「의좋은 형제」에서 가장 기억에 남는 장면과 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 형제가 마주쳐 얼싸안는 장면 — 서로를 아끼는 마음이 느껴져 가슴이 따뜻해졌다.","scoring_points":["장면을 썼어요","까닭을 썼어요"]},"explanation":["감상이에요.","273쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["형은 아우에게 볏단이 더 필요할 거라며 밤에 몰래 아우의 볏가리에 볏단을 옮겼어요.","아우도 형님에게 더 필요하다며 몰래 형의 볏가리에 볏단을 옮겼어요.","아침마다 볏단이 그대로라 형제는 어리둥절했어요.","어느 밤 길에서 마주친 형제는 서로의 마음을 알고 얼싸안았어요."],"title":"『국어』 268~271쪽 「의좋은 형제」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
