INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#12','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C10',2,'mc','auto','동아줄이 내려왔을 때 오누이의 마음은?',ARRAY['K2-1-u8-X15']::text[],false,'{"seq":12,"concept":"K2-1-u8-C10","difficulty":2,"kind":"mc","stem":"동아줄이 내려왔을 때 오누이의 마음은?","options":[{"t":"무척 기쁘고 안심한 마음","correct":true},{"t":"무서운 마음","mis":"K2-1-u8-X15"},{"t":"화난 마음","mis":"K2-1-u8-X15"}],"explanation":["기뻐요.","267쪽이에요.","예시예요."],"asset":{"type":"passage","lines":["엄마가 잔칫집에 가시며 모르는 사람이 오면 절대 문을 열어 주지 말라고 하셨어요.","고개에서 엄마를 잡아먹은 호랑이가 엄마인 척 「엄마가 왔단다.」 하고 찾아왔어요.","나무 위로 도망친 똘이는 호랑이에게 손에 기름을 바르고 올라오라고 했어요.","오누이는 하늘에서 내려온 동아줄을 타고 올라가 해와 달이 되었고, 썩은 동아줄을 잡은 호랑이는 떨어졌어요."],"title":"『국어』 264~267쪽 「해와 달이 된 오누이」(전래) 줄임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
