INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#19','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C1',3,'ox','auto','「우산 사용법」은 우산을 펴고 접는 방법을 알려 주는 글이다.',ARRAY['K2-1-u8-X02']::text[],false,'{"seq":19,"concept":"K2-1-u8-C1","difficulty":3,"kind":"ox","stem":"「우산 사용법」은 우산을 펴고 접는 방법을 알려 주는 글이다.","answer":"X","reason_options":[{"t":"함께 우산을 쓰는 따뜻하고 정다운 마음을 노래한 시라서","correct":true},{"t":"제목에 「사용법」이 있어서","mis":"K2-1-u8-X02"}],"mis":"K2-1-u8-X02","explanation":["마음을 노래한 시예요.","248쪽이에요.","시예요."],"asset":{"type":"scene","icon":"☂️","text":"「우산 사용법」(정연철) — 작은 우산 하나를 팔짱 끼고 어깨동무한 두 사람이 함께 쓰면 더 따뜻하고 정다워요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
