INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#21','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C9',3,'mc','auto','「팥죽 할멈과 호랑이」 대본에서 호랑이를 강물에 던진 것은?',ARRAY['K2-1-u8-X03']::text[],false,'{"seq":21,"concept":"K2-1-u8-C9","difficulty":3,"kind":"mc","stem":"「팥죽 할멈과 호랑이」 대본에서 호랑이를 강물에 던진 것은?","options":[{"t":"지게","correct":true},{"t":"멍석","mis":"K2-1-u8-X03"},{"t":"송곳","mis":"K2-1-u8-X03"}],"explanation":["지게예요.","지도서 347쪽이에요.","평가 대본이에요."],"asset":{"type":"speech","turns":[{"who":"호랑이","text":"어흥, 팥죽도 먹고 할머니도 잡아먹으러 왔다."},{"who":"해설","text":"알밤이 뻥 터지며 호랑이 눈에 박치기를 했어. 송곳이 엉덩이를 쿡 찔렀어."},{"who":"해설","text":"멍석이 호랑이를 둘둘 말고, 지게가 강물에 풍덩 던져 버렸어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
