INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#23','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C13',4,'sa','auto','「구름을」의 바른 발음을 [ ] 없이 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-1-u8-C13","difficulty":4,"kind":"sa","stem":"「구름을」의 바른 발음을 [ ] 없이 쓰세요.","answer":["구르믈"],"explanation":["구르믈이에요.","278쪽이에요.","기초 다지기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#24','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C5',4,'essay','teacher','신호를 주고받고 싶은 사람, 주고받고 싶은 신호, 그 신호에 담긴 뜻을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-1-u8-C5","difficulty":4,"kind":"essay","stem":"신호를 주고받고 싶은 사람, 주고받고 싶은 신호, 그 신호에 담긴 뜻을 쓰세요.","answer_guide":{"answer":"예: 동네 친구 — 양손으로 ㄴ 자 만들기 — 놀이터에서 만나자.","scoring_points":["사람과 신호를 썼어요","신호에 담긴 뜻을 썼어요"]},"explanation":["나만의 신호예요.","254쪽이에요.","보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u8_review_d#25','kor',2,1,'u8','','g2_1_kor_u8_review_d','unit_review','K2-1-u8-C12',4,'essay','teacher','모둠에서 인형극으로 꾸미고 싶은 장면, 필요한 인물, 드러내고 싶은 인물의 마음을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u8-C12","difficulty":4,"kind":"essay","stem":"모둠에서 인형극으로 꾸미고 싶은 장면, 필요한 인물, 드러내고 싶은 인물의 마음을 쓰세요.","answer_guide":{"answer":"예: 「해와 달이 된 오누이」 동아줄 장면 — 똘이, 순이, 호랑이 — 오누이의 간절한 마음","scoring_points":["장면과 인물을 썼어요","드러내고 싶은 마음을 썼어요"]},"explanation":["인형극 준비예요.","274쪽이에요.","지도서 339쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
